// Extraer datos del payload
const payload = $input.item.json.body;

// Validar que vengan los datos necesarios
if (!payload.email || !payload.password) {
  return {
    json: {
      success: false,
      error: 'Email y password son requeridos',
      code: 'MISSING_CREDENTIALS'
    }
  };
}

// Preparar datos para LDAP
return {
  json: {
    email: payload.email,
    password: payload.password,
    name: payload.name || '',
    surname: payload.surname || '',
    timestamp: new Date().toISOString()
  }
};

// Usuario autenticado correctamente por LDAP
const ldapData = $input.item.json;
const originalPayload = $('Validar Payload').item.json;

// Extraer rol desde grupos de LDAP
let role = 'usuario';

if (ldapData.memberOf) {
  const groups = Array.isArray(ldapData.memberOf) ? ldapData.memberOf : [ldapData.memberOf];

  if (groups.some(g => g.includes('CN=Administradores') || g.includes('CN=Admins'))) {
    role = 'administrador';
  } else if (groups.some(g => g.includes('CN=Farmaceuticos'))) {
    role = 'farmaceutico';
  } else if (groups.some(g => g.includes('CN=FIR'))) {
    role = 'FIR';
  }
}

// Crear payload del SSO token
const ssoPayload = {
  sub: ldapData.mail || originalPayload.email,
  email: ldapData.mail || originalPayload.email,
  name: ldapData.givenName || originalPayload.name || 'Usuario',
  surname: ldapData.sn || originalPayload.surname || '',
  role: role,
  hospital: 'HUNSC-Sur',
  exp: Math.floor(Date.now() / 1000) + (5 * 60) // Expira en 5 minutos
};

// Codificar en base64
const ssoToken = Buffer.from(JSON.stringify(ssoPayload)).toString('base64');

return {
  json: {
    success: true,
    ssoToken: ssoToken,
    user: {
      email: ssoPayload.email,
      name: ssoPayload.name,
      surname: ssoPayload.surname,
      role: ssoPayload.role
    }
  }
};

// Error de autenticación LDAP
const errorData = $input.item.json;

return {
  json: {
    success: false,
    error: 'Credenciales LDAP inválidas',
    code: 'LDAP_AUTH_FAILED',
    details: errorData.error || 'No se pudo autenticar con LDAP'
  }
};
